insert into public.knowledge_embeddings (content, source, section, metadata) values ($kb$Age Birth–3: Early Intervention

AGE: Birth–3 — Early Intervention

ENTITIES: Regional Center (Early Start), Medi-Cal, CCS, Private Insurance, Early Intervention therapists, CalABLE

ACTIONS: • Refer to RC immediately if developmental concerns
• 45-day assessment timeline
• IFSP within 45 days of referral
• IFSP review every 6 months
• Begin transition planning at 2.5 years
• Refer to school district for Part B evaluation
• Open CalABLE account (no minimum age — $19K/year tax-advantaged savings for disability expenses without affecting SSI/Medi-Cal)

TRANSITIONS: • Hospital → Home (NICU follow-up)
• Diagnosis → RC intake
• Age 2.5: Part C → Part B transition planning begins
• Age 3: IFSP → IEP transition

DOCUMENTS: IFSP, medical records, Early Start evaluations, transition plan, school district referral, CalABLE enrollment$kb$, $kb$age_timeline$kb$, $kb$age-birth-3$kb$, $kb${"code":"age-birth-3","title":"Age Birth–3: Early Intervention","category":"age-timeline","subcategory":"birth-3","source_ref":"Entity Matrix v9.4","origin":"entity-matrix-v9.4"}$kb$::jsonb);
insert into public.knowledge_embeddings (content, source, section, metadata) values ($kb$Age 3–5: Preschool / Early Childhood

AGE: 3–5 — Preschool / Early Childhood

ENTITIES: School District (IEP), Regional Center, Medi-Cal, CCS, Private Insurance, SELPA, CalABLE

ACTIONS: • IEP must be in place by 3rd birthday
• Inclusive preschool placement discussion (LRE)
• Triennial re-evaluation
• Choose preschool (Undivided: school tour checklist)
• Apply for SSI if eligible
• Apply for IHSS if eligible
• Open CalABLE account (no minimum age — $19K/year tax-advantaged savings for disability expenses without affecting SSI/Medi-Cal)

TRANSITIONS: • RC → School District (IFSP → IEP)
• Home → Preschool
• Preschool → Kindergarten (transition IEP)

DOCUMENTS: IEP, assessment reports, preschool tour checklist, SSI application, IHSS application, CalABLE enrollment$kb$, $kb$age_timeline$kb$, $kb$age-3-5$kb$, $kb${"code":"age-3-5","title":"Age 3–5: Preschool / Early Childhood","category":"age-timeline","subcategory":"3-5","source_ref":"Entity Matrix v9.4","origin":"entity-matrix-v9.4"}$kb$::jsonb);
insert into public.knowledge_embeddings (content, source, section, metadata) values ($kb$Age 5–11: Elementary School

AGE: 5–11 — Elementary School

ENTITIES: School District (IEP/504), RC, IHSS, SSI, Medi-Cal, CCS, Private Insurance, ERMHS, CalABLE

ACTIONS: • Annual IEP review
• Triennial re-evaluation
• Track IEP service delivery (use DRC tracking log)
• Request additional assessments if new concerns
• Monitor progress reports
• Address behavioral needs (BIP, ERMHS)
• Request IEE if disagree with assessments
• Open CalABLE account (no minimum age — $19K/year tax-advantaged savings for disability expenses without affecting SSI/Medi-Cal)

TRANSITIONS: • Kindergarten entry
• Grade-level transitions
• Elementary → Middle School (transition IEP)

DOCUMENTS: IEP, progress reports, assessment reports, BIP, service tracking log, IEE reports, CalABLE enrollment$kb$, $kb$age_timeline$kb$, $kb$age-5-11$kb$, $kb${"code":"age-5-11","title":"Age 5–11: Elementary School","category":"age-timeline","subcategory":"5-11","source_ref":"Entity Matrix v9.4","origin":"entity-matrix-v9.4"}$kb$::jsonb);
