insert into public.knowledge_embeddings (content, source, section, metadata) values ($kb$Age 18–22: Transition Age / Young Adult

AGE: 18–22 — Transition Age / Young Adult

ENTITIES: School District (IEP until 22/diploma), RC (adult services), DOR, SSI (adult criteria), IHSS, Medi-Cal, CalABLE, SNT

ACTIONS: • SSI re-determination at 18 (child → adult criteria)
• Age of majority: student may sign own IEP
• IEP continues until 22 or diploma
• RC adult services (supported living, day programs, employment)
• DOR vocational services
• Consider conservatorship/alternatives
• SNT planning

TRANSITIONS: • Age 18: legal adulthood, SSI transition
• High school → post-secondary/employment
• School district → adult RC services
• IEP ends at 22 or diploma

DOCUMENTS: IEP/ITP, SSI adult application, RC IPP (adult), DOR IPE, conservatorship/alternatives, SNT$kb$, $kb$age_timeline$kb$, $kb$age-18-22$kb$, $kb${"code":"age-18-22","title":"Age 18–22: Transition Age / Young Adult","category":"age-timeline","subcategory":"18-22","source_ref":"Entity Matrix v9.4","origin":"entity-matrix-v9.4"}$kb$::jsonb);
