insert into public.knowledge_embeddings (content, source, section, metadata) values ($kb$Equity — POS Spending Disparities

EQUITY BARRIER: POS Spending Disparities

AFFECTED: Latino/Hispanic families, Black families

BARRIERS: White children receive significantly more Regional Center spending per capita than Latino children. Disparities persist across majority of RCs despite state equity efforts.

EVIDENCE: $66M state investment attempted to close gap; 17 of 21 RCs still showed disparities.

SUPPORTS: Lanterman Act equity provisions, DDS equity reports, RC complaint process, DRC advocacy

WAYPOINT RESPONSE: Auto-generates IPP goal suggestions based on comparable services. Flags spending disparities. Helps families request equitable services with data.$kb$, $kb$equity$kb$, $kb$eq-pos-spending-dispa$kb$, $kb${"code":"eq-pos-spending-dispa","title":"Equity — POS Spending Disparities","category":"equity","subcategory":"pos-spending-dispa","source_ref":"Entity Matrix v9.4","origin":"entity-matrix-v9.4"}$kb$::jsonb);
insert into public.knowledge_embeddings (content, source, section, metadata) values ($kb$Equity — Language Access Barriers

EQUITY BARRIER: Language Access Barriers

AFFECTED: Non-English speaking families (especially Spanish, Chinese, Vietnamese, Korean, Tagalog, Armenian, Hmong speakers)

BARRIERS: RCs and schools failing to communicate in preferred language despite legal requirements. Assessment materials not available in home language. IEP meetings without qualified interpreters.

EVIDENCE: DRC publishes materials in 12 languages. IDEA requires interpreter at IEP meetings. Many schools use unqualified staff or children as interpreters.

SUPPORTS: IDEA interpreter requirement, Title VI language access, DRC multilingual resources, CA Ed Code requirements

WAYPOINT RESPONSE: Multilingual interface (10+ languages). Auto-translates IEP documents. Ensures interpreter request is included in every meeting notification.$kb$, $kb$equity$kb$, $kb$eq-language-access-ba$kb$, $kb${"code":"eq-language-access-ba","title":"Equity — Language Access Barriers","category":"equity","subcategory":"language-access-ba","source_ref":"Entity Matrix v9.4","origin":"entity-matrix-v9.4"}$kb$::jsonb);
insert into public.knowledge_embeddings (content, source, section, metadata) values ($kb$Equity — Late / Missed Diagnosis

EQUITY BARRIER: Late / Missed Diagnosis

AFFECTED: Hispanic/Latino children, Black children, rural families

BARRIERS: Hispanic/Latino students significantly less likely to be identified with autism. Black children more frequently misdiagnosed with ID when autism is present. Rural areas lack diagnostic specialists.

EVIDENCE: 40% disparity in autism identification for Hispanic/Latino students. Diagnostic delays of 2+ years for underserved communities.

SUPPORTS: Parent right to request evaluation at any time. Schools cannot use RTI to delay evaluation. IEE at public expense.

WAYPOINT RESPONSE: Screening questionnaire in multiple languages. Prompts parents to request evaluation. Tracks referral-to-diagnosis timeline. Flags delayed evaluations.$kb$, $kb$equity$kb$, $kb$eq-late-/-missed-diag$kb$, $kb${"code":"eq-late-/-missed-diag","title":"Equity — Late / Missed Diagnosis","category":"equity","subcategory":"late-/-missed-diag","source_ref":"Entity Matrix v9.4","origin":"entity-matrix-v9.4"}$kb$::jsonb);
insert into public.knowledge_embeddings (content, source, section, metadata) values ($kb$Equity — Rural Access Barriers

EQUITY BARRIER: Rural Access Barriers

AFFECTED: Families in rural and frontier CA counties

BARRIERS: Provider deserts for therapists, specialists, and IHSS caregivers. Lack of NPS and residential options. Limited RC service coordinator availability. Long travel distances.

EVIDENCE: 60%+ of CA counties lack sufficient IHSS caregivers. 10K+ teacher vacancies concentrated in rural/low-income districts. CCS specialist networks thin in rural areas.

SUPPORTS: Telehealth options expanding. RC vendored telehealth providers. DOR remote services.

WAYPOINT RESPONSE: Telehealth provider directory. Maps nearest specialists. Identifies RC-vendored remote services. Advocates for telehealth delivery of IEP services.$kb$, $kb$equity$kb$, $kb$eq-rural-access-barri$kb$, $kb${"code":"eq-rural-access-barri","title":"Equity — Rural Access Barriers","category":"equity","subcategory":"rural-access-barri","source_ref":"Entity Matrix v9.4","origin":"entity-matrix-v9.4"}$kb$::jsonb);
insert into public.knowledge_embeddings (content, source, section, metadata) values ($kb$Equity — Income-Related Barriers

EQUITY BARRIER: Income-Related Barriers

AFFECTED: Low-income families across all demographics

BARRIERS: SSI $2K resource trap prevents asset building. Attorney fees for SpEd due process prohibitive. Undivided at $115/mo unaffordable. Private evaluations cost $2K-$5K+. FCP for RC services.

EVIDENCE: CalABLE helps with SSI trap ($100K exemption). Pooled SNTs available. DRC provides free legal help for eligible cases. PTIs federally funded.

SUPPORTS: CalABLE, pooled SNTs, DRC free legal services, PTIs (TASK, Matrix), Legal Aid, IEE at public expense

WAYPOINT RESPONSE: Free navigation (replaces $115/mo Undivided). CalABLE calculator. IEE request generator. Connects to free legal resources.$kb$, $kb$equity$kb$, $kb$eq-income-related-bar$kb$, $kb${"code":"eq-income-related-bar","title":"Equity — Income-Related Barriers","category":"equity","subcategory":"income-related-bar","source_ref":"Entity Matrix v9.4","origin":"entity-matrix-v9.4"}$kb$::jsonb);
insert into public.knowledge_embeddings (content, source, section, metadata) values ($kb$Equity — Navigation Complexity Burden

EQUITY BARRIER: Navigation Complexity Burden

AFFECTED: ALL families, disproportionately affecting underserved communities

BARRIERS: 15-25+ entities to navigate simultaneously. Jargon-heavy processes. Overlapping timelines. No single point of coordination. Knowledge gap IS the disparity multiplier — families who know the system get more services.

EVIDENCE: DRC Common District Statements proves schools rely on parent ignorance. Undivided's business model built on this complexity. EdNavigator exists because navigation is overwhelming.

SUPPORTS: DRC publications, Undivided, EdNavigator, PTIs, parent support groups, non-attorney advocates

WAYPOINT RESPONSE: Central hub replacing 25+ entity interactions. Real-time advocacy coaching. Auto-tracks all timelines. Generates all letters/documents. Translates jargon. Equalizes knowledge access.$kb$, $kb$equity$kb$, $kb$eq-navigation-complex$kb$, $kb${"code":"eq-navigation-complex","title":"Equity — Navigation Complexity Burden","category":"equity","subcategory":"navigation-complex","source_ref":"Entity Matrix v9.4","origin":"entity-matrix-v9.4"}$kb$::jsonb);
